package com.tradequest.app;

final class LessonCatalog {
    private LessonCatalog() {}
    static String[][] all() {
        return new String[][] {
            {"01 · БАЗА","Японские свечи","Свеча содержит Open, High, Low и Close. Тело показывает разницу между открытием и закрытием, тени — крайние цены периода. Одна свеча не предсказывает будущее: оценивай последовательность и контекст."},
            {"02 · СТРУКТУРА","Тренд и боковик","Восходящий тренд формирует более высокие максимумы и минимумы, нисходящий — более низкие. Боковик движется в диапазоне. Ищи подтверждение структурой и заранее отмечай уровень отмены сценария."},
            {"03 · НАПРАВЛЕНИЕ","LONG и SHORT","LONG зарабатывает при росте цены, SHORT — при снижении. Перед входом сформулируй сценарий, точку отмены и план выхода. Само направление не даёт преимущества: важны качество входа, риск и дисциплина."},
            {"04 · УРОВНИ","Поддержка и сопротивление","Поддержка — область, где раньше активизировались покупатели; сопротивление — область продавцов. Это зоны, а не точные линии. Учитывай реакции, силу движения и возможный ретест."},
            {"05 · ИНДИКАТОРЫ","Moving Average и RSI","Скользящая средняя сглаживает цену, RSI оценивает импульс. Перекупленность не гарантирует разворот, пересечение средних запаздывает. Используй индикаторы как подтверждение."},
            {"06 · ОБЪЁМ","Объём и ликвидность","Объём показывает активность торгов. Ликвидность — возможность исполнить ордер без сильного влияния на цену. На тонком рынке спред и проскальзывание ухудшают результат."},
            {"07 · РИСК","Риск-менеджмент","Сначала выбери допустимый денежный убыток, затем расстояние до Stop Loss и только после этого размер позиции. Не увеличивай риск ради отыгрыша."},
            {"08 · ПЛЕЧО","Маржа и ликвидация","Плечо увеличивает номинал позиции относительно маржи, усиливая прибыль и убыток. Ликвидация зависит от maintenance margin, mark price и правил биржи. Тренажёр пока не моделирует точную ликвидацию."},
            {"09 · ВЫХОД","Take Profit и Stop Loss","TP фиксирует цель, SL ограничивает сценарий. Уровни должны учитывать структуру и допустимый риск. Если TP и SL задеты в одной OHLC-свече, порядок событий неизвестен."},
            {"10 · ПСИХОЛОГИЯ","Дисциплина трейдера","До сделки запиши причину входа, условие отмены и риск. Не мсти рынку и не пытайся отыграться. Оценивай соблюдение плана отдельно от финансового результата."},
            {"11 · АНАЛИТИКА","Журнал и статистика","Отслеживай не только win rate, но и среднюю прибыль, средний убыток, просадку и количество сделок. Маленькая выборка не доказывает устойчивость стратегии."},
            {"12 · ПРАКТИКА","Исторический тренажёр","Сначала показываются только свечи до точки решения. Вход моделируется по открытию следующей свечи, затем раскрывается история. Комиссии и funding пока не включены."},
            {"13 · СТРУКТУРА","Свинг-хай и свинг-лоу","Свинг-хай — локальный максимум, ограниченный более низкими максимумами по сторонам; свинг-лоу — локальный минимум с более высокими минимумами рядом. Последовательность HH и HL описывает восходящую структуру, LH и LL — нисходящую. Свинг подтверждается только после появления соседних свечей, поэтому его нельзя считать известным заранее.","Отметь последние два подтверждённых максимума и минимума. Сравни их порядок и запиши, где структура перестанет быть действительной."},
            {"14 · ПРОБОЙ","Пробой и ретест","Пробой диапазона — закрытие цены за границей области консолидации. Тень за уровнем сама по себе не подтверждает пробой. Ретест — возвращение к пробитой зоне с последующей реакцией. Цена может вернуться внутрь диапазона: это ложный пробой.","Сравни закрытие свечи с границей диапазона, затем дождись ретеста. Не считай касание уровня гарантией продолжения."},
            {"15 · СВЕЧИ","Поглощение и пин-бар","Поглощение описывает свечу, тело которой перекрывает тело предыдущей. Пин-бар имеет длинную тень и небольшое тело. Формации без контекста встречаются случайно. Важны место появления, направление старшего тренда и подтверждение следующими свечами.","Найди формацию у заранее отмеченной зоны и сравни её результат с такой же формацией в середине диапазона."},
            {"16 · ВОЛАТИЛЬНОСТЬ","ATR и диапазон цены","ATR измеряет средний истинный диапазон за выбранное число периодов и учитывает гэпы через сравнение High/Low с предыдущим Close. ATR не показывает направление, только масштаб движения. Его можно использовать для сравнения волатильности, но не как точную границу риска.","Сравни ATR с текущей ценой в процентах и проверь, не слишком ли близко расположен стоп относительно обычного шума."},
            {"17 · ИНДИКАТОРЫ","MACD и импульс","MACD — разница быстрой и медленной EMA; сигнальная линия сглаживает MACD, а гистограмма показывает расстояние между ними. Положительная гистограмма не означает обязательный рост, а пересечение запаздывает относительно цены.","Проверь, растёт или уменьшается гистограмма при обновлении максимума цены. Отмечай расхождение как предупреждение, а не готовый сигнал."},
            {"18 · ИНДИКАТОРЫ","Полосы Боллинджера","Полосы Боллинджера строятся вокруг скользящей средней на основе стандартного отклонения. Сужение часто совпадает со снижением волатильности, расширение — с её ростом. Касание верхней полосы не означает автоматическую продажу: в сильном тренде цена может идти вдоль полосы.","Сравни ширину полос в спокойном диапазоне и во время импульса. Не торгуй касание полосы без ценового контекста."},
            {"19 · РИСК","Соотношение риск / прибыль","R-множитель сравнивает потенциальную прибыль с заранее принятым убытком. Если риск равен 10 USDT, цель 20 USDT соответствует 2R. Win rate отдельно не описывает качество стратегии: важны средний выигрыш, средний убыток и издержки.","До входа запиши денежный риск и потенциальную прибыль. Не выбирай сделку только потому, что визуально цель кажется большой."},
            {"20 · РИСК","Расчёт размера позиции","Размер позиции выводится из допустимого убытка и расстояния до стопа. Сначала определяется риск в валюте счёта, затем цена входа и стоп, после чего рассчитывается количество актива. Плечо влияет на маржу и ликвидацию, но не заменяет расчёт убытка.","Уменьши размер позиции при более широком стопе, сохранив одинаковый допустимый денежный риск."},
            {"21 · СТАТИСТИКА","Математическое ожидание","Ожидание оценивает средний результат сделки: вероятность выигрыша умножается на средний выигрыш, вероятность проигрыша — на средний убыток, затем учитываются издержки. Для выводов нужна серия сделок с одинаковыми правилами.","Рассчитай ожидание на выборке и сравни его с результатом после условных комиссий. Не делай вывод по двум-трём сделкам."},
            {"22 · СТАТИСТИКА","Просадка и серии убытков","Просадка — снижение капитала от предыдущего максимума до последующего минимума. Серии убытков возможны даже у стратегии с положительным ожиданием. Размер риска должен позволять пережить неблагоприятную серию без эмоционального увеличения позиции.","Посмотри на максимальную историческую просадку и оцени, какой размер риска позволил бы продолжить работу без нарушения правил."},
            {"23 · ТЕСТИРОВАНИЕ","Ошибки бэктеста","Подглядывание в будущее возникает, если решение использует свечи, которые ещё не были доступны. Переоптимизация — подгонка параметров под прошлые данные. Проверяй правила на отдельном периоде, не использованном при настройке.","Проверь, что вход считается не раньше следующего доступного открытия, а параметры не выбирались по результату тестового периода."},
            {"24 · ИЗДЕРЖКИ","Комиссия, спред и проскальзывание","Комиссия взимается по правилам биржи, спред — разница лучшей цены покупки и продажи, проскальзывание — отличие ожидаемой цены от фактического исполнения. Частые сделки и низкая ликвидность могут заметно ухудшить результат. Текущий тренажёр не включает полный расчёт этих издержек.","При оценке стратегии отдельно выпиши комиссию входа и выхода, спред и возможное проскальзывание."}
        };
    }
}
